import{_ as a,o as n,c as s,ah as i}from"./chunks/framework.ojwJKwrc.js";const u=JSON.parse('{"title":"Runtime Semantics","description":"","frontmatter":{},"headers":[],"relativePath":"internals/cascade-limitations.md","filePath":"internals/cascade-limitations.md"}'),t={name:"internals/cascade-limitations.md"};function l(o,e,c,r,d,p){return n(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="runtime-semantics" tabindex="-1">Runtime Semantics <a class="header-anchor" href="#runtime-semantics" aria-label="Permalink to &quot;Runtime Semantics&quot;">​</a></h1><p>Celox uses event-driven execution with split evaluate and commit phases. This page defines the runtime ordering model for simultaneous and cascaded clock events.</p><h2 id="simultaneous-domains" tabindex="-1">Simultaneous domains <a class="header-anchor" href="#simultaneous-domains" aria-label="Permalink to &quot;Simultaneous domains&quot;">​</a></h2><p>All clock domains triggered at one simulation time observe the same committed state. Celox first evaluates their next-state logic into the Working region and only then commits all results to the Stable region.</p><div class="language-veryl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">veryl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assign gclk = clk;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>always_ff (clk) {</span></span>
<span class="line"><span>    cnt1 = cnt1 + 1;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>always_ff (gclk) {</span></span>
<span class="line"><span>    cnt2 = cnt2 + cnt1;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>When <code>clk</code> and <code>gclk</code> trigger together, <code>cnt2</code> reads the pre-update value of <code>cnt1</code>. Evaluation order therefore does not change the result.</p><h2 id="cascaded-clocks" tabindex="-1">Cascaded clocks <a class="header-anchor" href="#cascaded-clocks" aria-label="Permalink to &quot;Cascaded clocks&quot;">​</a></h2><p>A sequential update may itself create another clock edge:</p><div class="language-veryl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">veryl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>always_ff (clk) {</span></span>
<span class="line"><span>    clk_div = ~clk_div;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>always_ff (clk_div) {</span></span>
<span class="line"><span>    cnt = cnt + 1;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>After committing the first set of domains, Celox propagates combinational logic and examines triggered bits. Newly discovered domains are evaluated in another round of the same simulation step. The loop ends when no new event-producing change remains.</p><p>Conceptually, each round is:</p><ol><li>discover triggered domains;</li><li>evaluate every domain from the current Stable region;</li><li>commit their Working values together;</li><li>settle combinational logic and discover further triggers.</li></ol><p>The runtime may use a combined evaluate-and-commit kernel when exactly one domain can run without affecting cascade consistency. This is an implementation optimization and does not change the ordering model above.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>Combinational dependency cycles, including zero-delay cycles between clocks, are rejected during simulator construction.</li><li>Celox models RTL event behavior, not gate delays or a general-purpose SystemVerilog delta-cycle scheduler.</li></ul><p>User-facing guidance for dependency cycles is in <a href="/celox/guide/combinational-loops.html">Combinational Loops</a>.</p>`,16)])])}const h=a(t,[["render",l]]);export{u as __pageData,h as default};
